cd /workspace && ls -la output/ && python3 - <<'EOF'
import docx
d = docx.Document("output/offer_letter_filled.docx")
import re
def texts(doc):
    out=[]
    for p in doc.paragraphs: out.append(p.text)
    for t in doc.tables:
        for row in t.rows:
            for c in row.cells:
                for p in c.paragraphs: out.append(p.text)
    for s in doc.sections:
        for hf in (s.header,s.footer,s.first_page_header,s.first_page_footer):
            for p in hf.paragraphs: out.append(p.text)
    return out
allt="\n".join(texts(d))
print("---CONTENT---")
print(allt)
print("---CHECKS---")
print("unresolved {{}}:", re.findall(r"\{\{[^}]*\}\}", allt))
print("relocation mention:", [l for l in allt.splitlines() if 'reloc' in l.lower() or '7,125' in l])
EOF
